dir:


































  &DefaultButton;




function dir$dmloailog(p){
  this.constructor(p);
}
dir$dmloailog.prototype = new DirEvent();
dir$dmloailog.prototype.afterInit = function(){
  var p = this._dir;
}
dir$dmloailog.prototype.afterInit = function(renderType){
  var p = this._dir,g = p.grid()

dir$dmloailogDisabledMasterField(p, g);

}

function dir$dmloailogDisabledMasterField(p, g){

  if(p.valForm('ma_loai').trim() != '')
  {
    p.setDisabled('ma_loai', true);
  }
  else
  {
    p.setDisabled('ma_loai', false);
  }
}






	.control-label.ma_loai, .control-label.ten_loai
	{	

		color: #499b98;;
	}







declare @codeExistsNewMsg nvarchar(256), @codeExistsEditMsg nvarchar(256)
select @codeExistsNewMsg = case when '@@lan' = 'v' then N'Mã loại đã tồn tại' else N'Type code is exists' end
select @codeExistsEditMsg = case when '@@lan' = 'v' then N'Mã loại đã tồn tại' else N'Type code is exists' end
